<?php
namespace App\Http\Controllers;
use App\Models\{User,TutorGroup,CentreManagerGrant as Grant,CentreManagerAccessRequest as AccessRequest};
use App\Support\{CentreManagerAccess as A,DirectoryCatalog};
use Illuminate\Http\Request;
use Illuminate\Support\Str;
class CentreManagerAccessController extends Controller {
 private function actor(Request $r){return A::administrator($r->user());}
 private function view(string $name,array $data=[]){return response()->view('centre-access.'.$name,$data)->header('Cache-Control','private, no-store')->header('Referrer-Policy','no-referrer');}
 private function policy(Request $r):array {return $r->validate(['target'=>'required|integer|min:1','groups'=>'required|array|min:1|max:20','groups.*'=>'required|integer|min:1|distinct','areas'=>'required|array|min:1|max:5','areas.*'=>'required|in:'.implode(',',array_keys(A::AREAS)),'expires'=>'required|date_format:Y-m-d','ceo_locked'=>'nullable|boolean']);}
 public function index(Request $r){$u=$this->actor($r);$staff=User::where('active',true)->whereIn('role',DirectoryCatalog::STAFF_ROLES)->orderBy('name')->get();$groups=TutorGroup::where('active',true)->orderBy('name')->get();$requests=AccessRequest::orderByDesc('created_at')->paginate(15);$grants=Grant::orderBy('user_id')->get();$staffNames=User::whereIn('id',$grants->pluck('user_id')->merge($requests->pluck('target_user_id')))->pluck('name','id');return $this->view('index',compact('u','staff','groups','requests','grants','staffNames'));}
 public function preview(Request $r){$this->actor($r);$d=$this->policy($r);$preview=A::preview($r->user(),User::findOrFail($d['target']),array_map('intval',$d['groups']),$d['areas'],$d['expires'],(bool)($d['ceo_locked']??false));$token=(string)Str::uuid();return $this->view('preview',compact('preview','token'));}
 public function prepare(Request $r){$this->actor($r);$d=$this->policy($r);$x=$r->validate(['source_hash'=>'required|regex:/^[a-f0-9]{64}$/D','request_token'=>'required|uuid','reference'=>'required|string|min:5|max:1000','confirmed'=>'accepted']);$record=A::prepare($r->user(),(int)$r->session()->get('auth_version'),User::findOrFail($d['target']),array_map('intval',$d['groups']),$d['areas'],$d['expires'],(bool)($d['ceo_locked']??false),$x['source_hash'],$x['request_token'],$x['reference']);return to_route('centre-access.show',$record)->with('status','Access proposal prepared. No Centre Manager permissions have been activated.');}
 public function show(Request $r,AccessRequest $accessRequest){$u=$this->actor($r);abort_unless(A::intact($accessRequest),409,'Access proof needs investigation.');return $this->view('show',['u'=>$u,'record'=>$accessRequest,'preview'=>$accessRequest->details['preview']]);}
 public function review(Request $r,AccessRequest $accessRequest){$this->actor($r);$d=$r->validate(['version'=>'required|integer|in:1','accept'=>'required|boolean','reference'=>'required|string|min:5|max:1000','ceo_override'=>'nullable|boolean','confirmed'=>'accepted']);A::review($r->user(),(int)$r->session()->get('auth_version'),$accessRequest,1,(bool)$d['accept'],$d['reference'],(bool)($d['ceo_override']??false));return to_route('centre-access.show',$accessRequest)->with('status','Access review recorded. Activation remains a separate checked step.');}
 public function apply(Request $r,AccessRequest $accessRequest){$this->actor($r);$r->validate(['version'=>'required|integer|in:2','confirmed'=>'accepted']);A::apply($r->user(),(int)$r->session()->get('auth_version'),$accessRequest,2);return to_route('centre-access.show',$accessRequest)->with('status','Reviewed scoped Centre Manager access activated. The account role and existing private administration permissions are unchanged.');}
 public function revoke(Request $r,User $target){$this->actor($r);$d=$r->validate(['version'=>'required|integer|min:1','reference'=>'required|string|min:5|max:1000','confirmed'=>'accepted']);A::revoke($r->user(),(int)$r->session()->get('auth_version'),$target,(int)$d['version'],$d['reference']);return to_route('centre-access.index')->with('status','Scoped Centre Manager access revoked immediately; retained history and the account role are unchanged.');}
}
